import { basename, resolve } from 'node:path';
import { existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';

export { CASES, asciiJson };

// Only run when invoked directly (importable for tooling, e.g. the case-list doc).
if (process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}

input.command:
cd /tmp && node --input-type=module -e '
import { CASES, asciiJson } from "/tmp/difftest.mjs";
import fs from "node:fs";
const groups = [];
const seen = new Map();
for (let i = 0; i < CASES.length; i++) {
  const c = CASES[i];
  if (!seen.has(c.group)) { seen.set(c.group, []); groups.push(c.group); }
  seen.get(c.group).push({ n: i + 1, argv: c.argv });
}
const titles = {
  "normal": "Normal values (happy path)",
  "negative": "Negative values and cancelling sums",
  "equals": "The `--opt=value` form",
  "repeat": "Repeated options (last one wins)",
  "help": "Help flags and prefix matching",
  "required": "Missing required arguments",
  "invalid-int": "Invalid int values (Python int() rejects)",
  "exotic-int": "Valid exotic int values (Python int() accepts)",
  "repr": "repr()-exercising invalid values",
  "unrecognized": "Unrecognized arguments",
  "expected-one": "Option missing its value (expected one argument)",
  "competing": "Competing error kinds (ordering)"
};
let md = "";
md += "# difftest cases\n\n";
md += "Generated from the `CASES` array in `/tmp/difftest.mjs` (single source of truth).\n";
md += "Run the harness with `node /tmp/difftest.mjs /output/test11.mjs`.\n\n";
md += "Total cases: **" + CASES.length + "**\n\n";
md += "Each case is spawned twice with the identical argv array (`shell: false`):\n";
md += "once as `/workspace/dataset/test11_executable <argv>` and once as `node <entry> <argv>`.\n";
md += "Only the prog name is normalized (reference `test11_executable` -> basename of the entry);\n";
md += "stdout, stderr and exit status are then compared byte-for-byte.\n\n";
md += "Argv arrays below are shown as ASCII-safe JSON: every non-ASCII codepoint is rendered as `\\uXXXX`.\n\n";
md += "## Summary\n\n| group | cases | description |\n|---|---:|---|\n";
for (const g of groups) md += "| `" + g + "` | " + seen.get(g).length + " | " + (titles[g] || "") + " |\n";
md += "\n";
for (const g of groups) {
  md += "## " + (titles[g] || g) + " (`" + g + "`)\n\n";
  md += "| # | argv |\n|---:|---|\n";
  for (const e of seen.get(g)) {
    md += "| " + e.n + " | `" + asciiJson(e.argv).split("|").join("\\|") + "` |\n";
  }
  md += "\n";
}
fs.writeFileSync("/tmp/difftest-cases.md", md);
console.log("wrote", CASES.length, "cases");
'
